#pragma once

// Sound effects. All sounds are generated by code at start-up (no sound files needed)
// and played through the Windows waveOut API on several channels, so they can overlap.
enum class Sfx { Slice, Bomb, Miss, Combo, LevelUp, GameOver, Blip, Count };

void soundInit();
void soundShutdown();
void soundPlay(Sfx s);
void soundSetEnabled(bool on);
bool soundEnabled();
